export function emptyEpisode(projectId: Id, order: number, title = ""): Episode {
    const at = nowIso();
    return {
        id: createId("ep"),
        projectId,
        order,
        title,
        story: emptyEpisodeStory(),
        shotFilters: normalizeShotFilters(undefined),
        createdAt: at,
        updatedAt: at,
