    projectId: Id,
    episodeId: Id,
    order: number,
    shotNumber: string,
    durationSec: number,
    beatId?: Id,
): Shot {
    return {
        id: createId("sht"),
        projectId,
        episodeId,
        order,
        shotNumber,
        status: "draft",
        firstFrame: emptySlot(),
        lastFrame: emptySlot(),
        clip: emptySlot(),
        category: "",
        durationSec,
        content: "",
        notes: "",
        sceneCloseup: "",
        sound: "",
        emotion: "",
        cameraAngle: "",
        cameraGear: "",
        focalLength: "",
